  id: number;
  account_id: number;
  amount: number;
  currency: string;
  memo: string | null;
  created_at_epoch_ms: number;
};

export function listRecentEntries(db: Database.Database, accountId: number): Array<{ id: number; formattedAmount: string; currency: string; memo: string }> {
  const rows = db
    .prepare(
      "SELECT id, account_id, amount, currency, memo, created_at_epoch_ms FROM ledger_entries WHERE account_id = ? ORDER BY created_at_epoch_ms DESC, id DESC LIMIT 50",
    )
    .all(accountId) as LedgerEntry[];
  return rows.map(row => ({
    id: row.id,
    formattedAmount: row.amount.toFixed(2),
    currency: row.currency.toUpperCase(),
    memo: row.memo ?? "",
  }));
}

