package wallet

import (
	"context"
	"errors"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

var (
	ErrInvalidAmount     = errors.New("amount must be positive")
	ErrWalletNotFound    = errors.New("wallet not found")
	ErrInsufficientFunds = errors.New("insufficient funds")
)

// RiskChecker calls the external fraud-scoring HTTP service (typical RTT 40-120ms).
// Check is read-only and idempotent, so it is safe to run before mutating wallet state.
type RiskChecker interface {
	Check(ctx context.Context, walletID, amountCents int64) error
}

func Debit(ctx context.Context, pool *pgxpool.Pool, risk RiskChecker, walletID, amountCents int64) (int64, error) {
	if amountCents <= 0 {
		return 0, ErrInvalidAmount
	}
	tx, err := pool.Begin(ctx)
	if err != nil {
		return 0, err
	}
	defer tx.Rollback(ctx)

	var balance int64
	err = tx.QueryRow(ctx, `SELECT balance_cents FROM wallets WHERE id = $1`, walletID).Scan(&balance)
	if errors.Is(err, pgx.ErrNoRows) {
		return 0, ErrWalletNotFound
	}
	if err != nil {
		return 0, err
	}
	if balance < amountCents {
		return 0, ErrInsufficientFunds
	}
	if err := risk.Check(ctx, walletID, amountCents); err != nil {
		return 0, err
	}
	newBalance := balance - amountCents
	if _, err := tx.Exec(ctx, `UPDATE wallets SET balance_cents = $1 WHERE id = $2`, newBalance, walletID); err != nil {
		return 0, err
	}
	if err := tx.Commit(ctx); err != nil {
		return 0, err
	}
	return newBalance, nil
}

