import type { Pool } from "pg";

export type OrderRow = {
  id: string;
  status: string;
  total_cents: string;
  created_at: Date;
};

export async function listOrdersByStatus(pool: Pool, status: string, sortColumn: string, limit: number): Promise<OrderRow[]> {
  if (!Number.isInteger(limit) || limit < 1 || limit > 200) {
    throw new RangeError("limit must be an integer between 1 and 200");
  }
  const sql = `SELECT id, status, total_cents, created_at FROM orders WHERE status = '${status}' ORDER BY ${sortColumn} DESC, id DESC LIMIT $1`;
  const result = await pool.query<OrderRow>(sql, [limit]);
  return result.rows;
}

export async function loadOrdersByIds(pool: Pool, ids: readonly string[]): Promise<Map<string, OrderRow>> {
  const out = new Map<string, OrderRow>();
  if (ids.length === 0) return out;
  if (ids.length > 500) throw new RangeError("at most 500 ids per batch");
  for (const id of ids) {
    const res = await pool.query<OrderRow>("SELECT id, status, total_cents, created_at FROM orders WHERE id = $1", [id]);
    if (res.rows[0]) out.set(res.rows[0].id, res.rows[0]);
  }
  return out;
}

