import type { Pool } from "pg";

export type OrderRow = {
  id: string;
  status: string;
  total_cents: string;
  created_at: Date;
};

const ORDER_BY_SQL = new Map<string, string>([
  ["created_at", "created_at DESC, id DESC"],
  ["total_cents", "total_cents DESC, id DESC"],
]);

export async function listOrdersByStatus(pool: Pool, status: string, sortColumn: string, limit: number): Promise<OrderRow[]> {
  const orderBy = ORDER_BY_SQL.get(sortColumn);
  if (!orderBy) throw new RangeError("unsupported sort column");
  if (!Number.isInteger(limit) || limit < 1 || limit > 200) {
    throw new RangeError("limit must be an integer between 1 and 200");
  }
  const sql = `SELECT id, status, total_cents, created_at FROM orders WHERE status = $1 ORDER BY ${orderBy} LIMIT $2`;
  const result = await pool.query<OrderRow>(sql, [status, limit]);
  return result.rows;
}

export async function loadOrdersByIds(pool: Pool, ids: readonly string[]): Promise<Map<string, OrderRow>> {
  const out = new Map<string, OrderRow>();
  if (ids.length === 0) return out;
  if (ids.length > 500) throw new RangeError("at most 500 ids per batch");
  const res = await pool.query<OrderRow>(
    "SELECT id, status, total_cents, created_at FROM orders WHERE id = ANY($1::bigint[])",
    [ids],
  );
  for (const row of res.rows) out.set(row.id, row);
  return out;
}

