import type { Pool, RowDataPacket } from "mysql2/promise";

export type ProductRow = RowDataPacket & {
  id: number;
  sku: string;
  name: string;
};

export async function loadProductsByIds(pool: Pool, ids: readonly number[]): Promise<ProductRow[]> {
  if (ids.length > 500) throw new RangeError("at most 500 ids per batch");
  const placeholders = ids.map(() => "?").join(", ");
  const [rows] = await pool.query<ProductRow[]>(
    `SELECT id, sku, name FROM products WHERE id IN (${placeholders}) ORDER BY id ASC`,
    [...ids],
  );
  return rows;
}

export async function insertProduct(pool: Pool, sku: string, name: string): Promise<"created" | "duplicate"> {
  try {
    await pool.execute("INSERT INTO products (sku, name) VALUES (?, ?)", [sku, name]);
    return "created";
  } catch {
    return "duplicate";
  }
}

